<?php
namespace App\Http\Controllers;
use App\Models\Conversation; use App\Models\Gig; use App\Models\Message; use Illuminate\Http\Request;
class MessageController extends Controller { public function start(Request $r,Gig $gig){abort_unless($gig->seller_id!==auth()->id(),422);$c=Conversation::firstOrCreate(['buyer_id'=>auth()->id(),'seller_id'=>$gig->seller_id,'gig_id'=>$gig->id]);return redirect()->route('messages.show',$c); } public function show(Conversation $conversation){abort_unless(in_array(auth()->id(),[$conversation->buyer_id,$conversation->seller_id]),403);$conversation->load('messages.sender','gig');return view('messages.show',compact('conversation'));} public function send(Request $r,Conversation $conversation){abort_unless(in_array(auth()->id(),[$conversation->buyer_id,$conversation->seller_id]),403);$data=$r->validate(['body'=>'required|string|max:5000']);Message::create(['conversation_id'=>$conversation->id,'sender_id'=>auth()->id(),'body'=>$data['body']]);return back();} }
